import React, { useId } from 'react';
import { useKainBain } from '../../context/KainBainContext';
import { Modal } from '../Modal';
import { QueueOrderList } from '../observability/widgets/QueueOrderList';
import { useScheduledQueue } from '../../hooks/useScheduledQueue';

/***
 * MARK: QueuePopupModal
 * @description Dialog listing the execution queue in its current dispatch order.
 * Backed by the shared `useScheduledQueue` hook (global scope) and the shared
 * `QueueOrderList` rendering, so it never forks the monitor's queue markup.
 * Loading, empty, and error + Retry states mirror `ChangelogModal`, except a
 * failed refresh keeps the last known rows visible under the alert (a stale
 * queue is more useful operationally than a blank panel). Row click
 * opens the task in the Slide-Over Inspector via the context's
 * `setSelectedTask`. Footer reconciles the chip's open-task count with the
 * dispatchable queue length so a silent mismatch never masquerades as a bug.
 * @example <QueuePopupModal counted={3} onClose={() => setOpen(false)} />
 * @param {Function} props.onClose - Called when the dialog should close.
 * @param {number} [props.counted] - Open-task count shown by the chip.
 * @param {number} [props.openQueueDepth] - Alias for `counted`.
 * @param {Object} [props.engineState] - Optional engine state carrying openQueueDepth.
 ***/
export function QueuePopupModal({ onClose, counted, openQueueDepth, engineState }) {
  const context = useKainBain();
  const setSelectedTask = context?.setSelectedTask;
  const contextEngineState = context?.engineState;
  const stateForCount = engineState || contextEngineState || {};
  const titleId = useId();
  const descId = useId();

  const countedValue =
    typeof counted === 'number'
      ? counted
      : typeof openQueueDepth === 'number'
        ? openQueueDepth
        : typeof stateForCount?.openQueueDepth === 'number'
          ? stateForCount.openQueueDepth
          : null;

  const { items, loading, error, refresh } = useScheduledQueue({
    projectScope: 'all',
    enabled: true,
  });

  const shown = Array.isArray(items) ? items.length : 0;
  const countedDisplay = countedValue == null ? shown : countedValue;
  const countsDiffer = countedValue != null && countedValue !== shown;

  const handleSelect = (item) => {
    if (typeof setSelectedTask === 'function') {
      setSelectedTask(item);
    }
    // Keep the modal open so the operator can keep debugging; the inspector
    // rides on top via its own slide-over. (No auto-close: preserves evidence.)
  };

  return (
    <Modal
      onClose={onClose}
      labelledBy={titleId}
      describedBy={descId}
      dialogClassName="w-full max-w-2xl max-h-[80vh] flex flex-col bg-surface-container border border-border-standard rounded-md shadow-2xl overflow-hidden"
    >
      <div className="flex items-start justify-between gap-3 px-4 py-3 border-b border-border-standard shrink-0">
        <div className="min-w-0">
          <h2 id={titleId} className="text-sm font-bold text-on-surface">
            Queue — all projects
          </h2>
          <p id={descId} className="text-[11px] font-mono text-text-muted">
            {/* "#1 runs next" tracks the listed queue, not the chip count:
                when every counted task is failed/waiting-human the list is
                empty and nothing runs next. */}
            #{shown >= 1 ? '1' : '—'} runs next · {countedDisplay} open
            {countedDisplay === 1 ? ' task' : ' tasks'} counted
          </p>
        </div>
        <button
          type="button"
          onClick={onClose}
          aria-label="Close queue"
          className="px-2 py-1 min-h-[44px] rounded-sm bg-surface-container-high hover:bg-surface-container-highest text-on-surface-variant hover:text-on-surface text-xs font-bold transition-colors cursor-pointer shrink-0"
        >
          Close
        </button>
      </div>

      <div className="overflow-y-auto px-2 py-2 grow min-h-[120px]">
        {loading && items.length === 0 && (
          <p role="status" className="px-4 py-6 text-sm text-text-muted">
            Loading queue…
          </p>
        )}
        {error && (
          <div className="space-y-2 px-4 py-4">
            <p role="alert" className="text-sm text-on-surface">
              Could not refresh the queue.
              {items.length > 0 ? ' Showing the last known queue below.' : ''}
            </p>
            <p className="text-[11px] font-mono text-text-muted">{error}</p>
            <button
              type="button"
              onClick={refresh}
              className="px-3 py-1.5 min-h-[44px] rounded-sm bg-primary text-on-primary text-xs font-bold hover:opacity-90 transition-opacity cursor-pointer"
            >
              Retry
            </button>
          </div>
        )}
        {/* Fail-safe: a failed refresh never blanks a previously loaded
            queue — rows stay visible under the alert until a fetch succeeds.
            The empty state renders only after a clean load of zero items. */}
        {(items.length > 0 || (!loading && !error)) && (
          <QueueOrderList
            items={items}
            engineState={stateForCount}
            schedulerRunning={stateForCount?.schedulerRunning}
            onSelectTask={handleSelect}
          />
        )}
      </div>

      <div className="px-4 py-2 border-t border-border-standard text-[10px] font-mono text-text-muted">
        <span data-testid="queue-reconciliation">
          {countedDisplay} open tasks counted · {shown} shown in the dispatch queue
        </span>
        {countsDiffer && (
          <span className="block mt-1">
            Failed, cancelled, waiting-human, and human-stage tasks count toward the number but never dispatch. Blocked and paused tasks do list — sorted last with their reason.
          </span>
        )}
      </div>
    </Modal>
  );
}

/***
 * MARK: QueuePopupModal default
 * @description Default export alias for QueuePopupModal.
 * @example <QueuePopupModal onClose={() => {}} />
 ***/
export default QueuePopupModal;

/* eslint-disable react-hooks/preserve-manual-memoization */
import { useCallback, useEffect, useRef, useState } from 'react';
import { api } from '../services/api';
import { subscribeObservability } from '../services/observabilityEvents';
import { logger } from '../services/logger';

/***
 * MARK: useScheduledQueue
 * @description Shared frontend hook for the dispatch-ordered queue shown by the
 *   Now Playing bar's queue popup (and any future queue surface). Data source
 *   is the global observability snapshot (`api.observabilityStatus(undefined)`
 *   serves every project in dispatch order, so no new endpoint was needed).
 *   Fetches on enable only, refreshes on observability invalidations, and
 *   keeps a 15 s safety poll plus visibility/focus returns. The monitor
 *   dashboard deliberately keeps its own inline fetch: it publishes metrics
 *   and queue atomically from one response with monitor-only guards
 *   (TASK_UPDATED active-task filter, hidden-tab gating, a staleness rule),
 *   which this queue-only hook does not replicate. The return contract is
 *   exactly four fields (`items`, `loading`, `error`, `refresh`) — callers
 *   destructure those, nothing else. A missing API method surfaces as
 *   `error`, never as a silent empty queue; a malformed payload logs a
 *   warning and fails safe to an empty list.
 * @example const { items, loading, error, refresh } = useScheduledQueue({ projectScope: 'all', enabled: isOpen })
 * @param {Object} [opts]
 * @param {string} [opts.projectScope='all'] - 'all' or a project id.
 * @param {boolean} [opts.enabled=false] - Fetching is off until this is true.
 * @returns {{
 *   items: Array<Object>,
 *   loading: boolean,
 *   error: string|null,
 *   refresh: () => void,
 * }}
 ***/
export function useScheduledQueue({ projectScope = 'all', enabled = false } = {}) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const mountedRef = useRef(true);
  const inFlightRef = useRef(false);
  const dirtyRef = useRef(false);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const fetchQueue = useCallback(
    async (refresh = false) => {
      if (!enabled) return;
      if (inFlightRef.current) {
        if (refresh) dirtyRef.current = true;
        return;
      }
      inFlightRef.current = true;
      // This fetch absorbs all pending invalidations (mirrors the dashboard's
      // `dirty = false` at load start): only refresh requests arriving
      // mid-flight chain a follow-up in the finally block below.
      dirtyRef.current = false;
      if (mountedRef.current) {
        setLoading(true);
      }
      try {
        const projectId =
          projectScope && projectScope !== 'all' ? projectScope : undefined;
        if (typeof api?.observabilityStatus !== 'function') {
          // Fail loud instead of as a silent empty queue: a missing API
          // method is a wiring bug and "Queue is Clear" would be a lie.
          throw new Error('Queue endpoint is unavailable');
        }
        const response = await api.observabilityStatus(projectId, refresh);
        if (!mountedRef.current) return;
        const rawQueue =
          response?.observability?.queue ??
          response?.queue ??
          (Array.isArray(response) ? response : null);
        if (rawQueue != null && !Array.isArray(rawQueue)) {
          // Malformed payload: report it, then fail safe to an empty list so
          // the UI renders the empty state instead of crashing.
          logger.warn('Scheduled queue payload was not an array; treating as empty');
          setItems([]);
        } else {
          setItems(rawQueue ?? []);
        }
        setError(null);
      } catch (err) {
        logger.error('Failed to fetch scheduled queue', err);
        if (mountedRef.current) {
          setError(err?.message || 'Failed to load queue');
        }
      } finally {
        inFlightRef.current = false;
        if (mountedRef.current) {
          setLoading(false);
        }
        if (mountedRef.current && dirtyRef.current) {
          dirtyRef.current = false;
          void fetchQueue(true);
        }
      }
    },
    [enabled, projectScope],
  );

  useEffect(() => {
    if (!enabled) return undefined;
    void fetchQueue();
    return undefined;
  }, [enabled, fetchQueue]);

  useEffect(() => {
    if (!enabled) return undefined;
    let debounceTimer = null;
    const scheduleRefresh = () => {
      dirtyRef.current = true;
      if (!debounceTimer) {
        debounceTimer = setTimeout(() => {
          debounceTimer = null;
          if (mountedRef.current) {
            void fetchQueue(true);
          }
        }, 500);
      }
    };
    const unsubscribe = subscribeObservability((event) => {
      if (
        event?.projectId &&
        projectScope &&
        projectScope !== 'all' &&
        event.projectId !== projectScope
      ) {
        return;
      }
      scheduleRefresh();
    });
    const interval = setInterval(() => void fetchQueue(true), 15000);
    const onVisibility = () => {
      if (document.visibilityState !== 'hidden') void fetchQueue(true);
    };
    document.addEventListener('visibilitychange', onVisibility);
    window.addEventListener('focus', onVisibility);
    return () => {
      unsubscribe();
      clearInterval(interval);
      clearTimeout(debounceTimer);
      document.removeEventListener('visibilitychange', onVisibility);
      window.removeEventListener('focus', onVisibility);
    };
  }, [enabled, fetchQueue, projectScope]);

  const refresh = useCallback(() => {
    void fetchQueue(true);
  }, [fetchQueue]);

  return { items, loading, error, refresh };
}

/***
 * MARK: useScheduledQueue default
 * @description Default export alias for useScheduledQueue.
 * @example useScheduledQueue({ enabled: true }) => { items: [], loading: false }
 ***/
export default useScheduledQueue;

import { formatTaskTitleFirstLine } from '../../tasks/taskFormatters';

/***
 * MARK: itemCardClass
 * @description Resolves the card border/background styling for a queue item.
 * @param {boolean} active
 * @param {boolean} waiting
 * @param {boolean} blocked
 * @returns {string}
 * @example itemCardClass(true, false, false) // => 'bg-emerald-950/30 ...'
 ***/
const itemCardClass = (active, waiting, blocked) => {
  if (active)
    return 'bg-emerald-950/30 border-emerald-500/70 shadow-[0_0_12px_rgba(16,185,129,0.15)]';
  if (waiting) return 'bg-amber-950/20 border-amber-500/50';
  if (blocked) return 'bg-slate-900/60 border-rose-900/40 opacity-70';
  return 'bg-slate-900/80 border-slate-800 hover:border-slate-700';
};

/***
 * MARK: itemBadgeClass
 * @description Resolves the priority tag badge class for a queue item.
 * @param {boolean} active
 * @param {boolean} waiting
 * @param {boolean} blocked
 * @returns {string}
 * @example itemBadgeClass(false, false, true) // => 'bg-rose-950 text-rose-300 ...'
 ***/
const itemBadgeClass = (active, waiting, blocked) => {
  if (active) return 'bg-emerald-950 text-emerald-400 border-emerald-500/50 animate-pulse';
  if (waiting) return 'bg-amber-950 text-amber-300 border-amber-500/50';
  if (blocked) return 'bg-rose-950 text-rose-300 border-rose-500/50';
  return 'bg-slate-800 text-slate-300 border-slate-700';
};

/***
 * MARK: QueueOrderList
 * @description Presentational queue list: renders the autonomous execution queue
 * in dispatch order (#1, #2, #3, ...) with stage progress, priority reasoning,
 * project tags, dependency warning indicators, and a blocked/waiting reason.
 * Pure presentation: data comes in via `items` (the monitor widget passes it
 * as `scheduledQueue`); row activation is surfaced through
 * `onSelectTask(item)`, so callers can open an inspector or perform other
 * actions. `schedulerRunning` drives the empty-state wording; `compact` is
 * reserved for dense surfaces.
 * @example <QueueOrderList items={queue} engineState={engineState} onSelectTask={openTask} />
 * @param {Array<Object>} [props.items] - Ordered queue items.
 * @param {Array<Object>} [props.scheduledQueue] - Alias for `items` (monitor widget's historical prop name).
 * @param {Object} [props.engineState] - Engine state (drives the single-active invariant).
 * @param {boolean} [props.schedulerRunning] - False shows a stopped empty state.
 * @param {Function} [props.onSelectTask] - Called with the clicked queue item.
 * @param {boolean} [props.compact] - Density hint (currently cosmetic).
 * @returns {JSX.Element}
 ***/
export function QueueOrderList({
  items,
  scheduledQueue,
  engineState = {},
  schedulerRunning,
  onSelectTask,
  compact = false,
}) {
  const resolvedItems = Array.isArray(items)
    ? items
    : Array.isArray(scheduledQueue)
      ? scheduledQueue
      : [];

  const handleSelect = typeof onSelectTask === 'function' ? onSelectTask : null;
  const schedulerStopped = schedulerRunning === false;
  // Rows are interactive only when a selection handler is wired (the queue
  // popup opens the inspector); handler-less surfaces like the monitor keep
  // the original plain-div rows — never focusable buttons that do nothing.
  const interactive = typeof handleSelect === 'function';

  const handleRowKeyDown = (event, item) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handleSelect(item);
    }
  };

  const emptyState = (
    <div
      className={`h-full flex flex-col items-center justify-center p-6 text-center text-slate-400 font-mono ${
        compact ? 'text-[10px]' : 'text-xs'
      }`}
    >
      <span className="text-3xl mb-2 opacity-50">✨</span>
      <p className="font-bold text-slate-300">
        {schedulerStopped ? 'Scheduler Stopped' : 'Queue is Clear'}
      </p>
      <p className="text-[11px] mt-1 text-slate-400">
        {schedulerStopped
          ? 'Autonomous execution is off. Start the scheduler to resume pickup.'
          : 'Idle — waiting for work. New tasks dispatch automatically.'}
      </p>
    </div>
  );

  return (
    <div
      // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- keyboard-scrollable widget body (WCAG 2.1.1)
      tabIndex={0}
      role="group"
      aria-label="Queue order list"
      className={`flex-1 p-2.5 space-y-2 overflow-y-auto custom-scrollbar bg-[#080c16] ${
        compact ? 'p-1.5 space-y-1.5' : ''
      }`}
    >
      {resolvedItems.length === 0
        ? emptyState
        : resolvedItems.map((item, idx) => {
        const isItemActive =
          engineState?.status === 'running' &&
          engineState?.activeTaskId != null &&
          String(item.id) === String(engineState.activeTaskId);
        const isBlocked = item.isBlocked || item.status === 'blocked';
        const isWaiting = item.status === 'waiting_human';
        const reason =
          item.priorityReason ||
          item.waitingReason ||
          item.blockedReason ||
          item.blocker ||
          'Queued';

        return (
          <div
            key={item.id || idx}
            data-testid={`queue-item-${item.id}`}
            {...(interactive
              ? {
                  role: 'button',
                  tabIndex: 0,
                  onClick: () => handleSelect(item),
                  onKeyDown: (event) => handleRowKeyDown(event, item),
                }
              : {})}
            className={`p-2.5 rounded-md border backdrop relative overflow-hidden ${interactive ? 'cursor-pointer ' : ''}${itemCardClass(
              isItemActive,
              isWaiting,
              isBlocked,
            )}`}
          >
            {/* Header Row: Rank Badge + Priority Tag */}
            <div className="flex items-center justify-between gap-2 mb-1.5">
              <div className="flex items-center gap-1.5 min-w-0">
                <span
                  className={`w-5 h-5 rounded flex items-center justify-center text-[10px] font-mono font-black shrink-0 ${
                    isItemActive
                      ? 'bg-emerald-500 text-slate-950 shadow-sm'
                      : 'bg-slate-800 text-slate-300'
                  }`}
                >
                  #{item.queueOrder || idx + 1}
                </span>
                <span className="text-[10px] font-mono text-slate-400 uppercase font-semibold truncate">
                  {item.projectName || 'Project'}
                </span>
              </div>

              <span
                className={`text-[9px] px-1.5 py-0.2 rounded border font-mono uppercase tracking-wider shrink-0 ${itemBadgeClass(
                  isItemActive,
                  isWaiting,
                  isBlocked,
                )}`}
              >
                {reason}
              </span>
            </div>

            {/* Task Title */}
            <h4 className="text-xs font-bold text-slate-100 line-clamp-2 leading-tight">
              {formatTaskTitleFirstLine(item)}
            </h4>

            {/* Task Metadata Footer */}
            <div className="mt-2 pt-1.5 border-t border-slate-800/80 flex items-center justify-between text-[10px] font-mono text-slate-400">
              <span className="flex items-center gap-1 text-slate-300 truncate max-w-[70%]">
                <span className="text-emerald-400">▸</span>
                <span className="truncate">{item.currentStageName || 'Stage'}</span>
              </span>
              <span className="shrink-0">KB-{item.id?.slice(0, 4)?.toUpperCase() || 'TASK'}</span>
            </div>

            {isItemActive && (
              <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-emerald-500" />
            )}
          </div>
        );
      })}
    </div>
  );
}

/***
 * MARK: QueueOrderList default
 * @description Default export alias for QueueOrderList.
 * @example <QueueOrderList items={queue} />
 ***/
export default QueueOrderList;
===WIDGET===
import { QueueOrderList } from './QueueOrderList';

/***
 * MARK: QueueOrderWidget
 * @description Thin wrapper around `QueueOrderList` for the monitor dashboard.
 * Accepts the historical `scheduledQueue` prop (plus `engineState` and
 * `schedulerRunning`) and maps it onto the presentational list's `items`.
 * The shared `QueueOrderList` is the single source for the queue rendering,
 * so this widget never forks its markup.
@example <QueueOrderWidget scheduledQueue={queue} engineState={engineState} schedulerRunning={true} />
 ***/
export function QueueOrderWidget(props) {
  const items = Array.isArray(props?.scheduledQueue) ? props.scheduledQueue : props?.items;
  return (
    <QueueOrderList
      {...props}
      items={items}
      scheduledQueue={items}
    />
  );
}

export { QueueOrderList } from './QueueOrderList';

export default QueueOrderWidget;

// @vitest-environment jsdom
import { expect, test, vi, beforeEach } from 'vitest';
import { screen, fireEvent, waitFor, act } from '@testing-library/react';
import '@testing-library/jest-dom';
import { QueuePopupModal } from './QueuePopupModal';
import { renderWithKainBain } from '../../testUtils';
import { invalidateObservability } from '../../services/observabilityEvents';
import React from 'react';

vi.mock('../../services/api', () => ({
  api: {
    observabilityStatus: vi.fn(async () => ({
      observability: {
        queue: [
          { id: 'task-1', title: 'First', projectName: 'P', currentStageName: 'Work', queueOrder: 1, priorityReason: 'Queued' },
        ],
      },
    })),
    getRunnerMonitor: vi.fn(async () => ({ liveAssignments: [] })),
    systemStatus: vi.fn(async () => ({ build: null })),
    deployChangelog: vi.fn(async () => ({ changelog: null, reason: 'not-baked' })),
  },
}));

import { api } from '../../services/api';

beforeEach(() => {
  vi.clearAllMocks();
  api.observabilityStatus.mockResolvedValue({
    observability: {
      queue: [
        { id: 'task-1', title: 'First', projectName: 'P', currentStageName: 'Work', queueOrder: 1, priorityReason: 'Queued' },
      ],
    },
  });
});

test('opens and lists queue rows in order', async () => {
  const onClose = vi.fn();
  const setSelectedTask = vi.fn();
  renderWithKainBain(<QueuePopupModal counted={2} onClose={onClose} />, { setSelectedTask, engineState: { openQueueDepth: 2 } });
  await waitFor(() => expect(screen.getByTestId('queue-item-task-1')).toBeInTheDocument());
  expect(screen.getByText('First')).toBeInTheDocument();
  fireEvent.click(screen.getByTestId('queue-item-task-1'));
  expect(setSelectedTask).toHaveBeenCalled();
  fireEvent.click(screen.getByRole('button', { name: 'Close queue' }));
  expect(onClose).toHaveBeenCalled();
});

test('empty state renders Queue is Clear', async () => {
  api.observabilityStatus.mockResolvedValue({ observability: { queue: [] } });
  renderWithKainBain(<QueuePopupModal counted={0} onClose={() => {}} />, { engineState: { openQueueDepth: 0 } });
  await waitFor(() => expect(screen.getByText('Queue is Clear')).toBeInTheDocument());
});

test('error state shows retry', async () => {
  api.observabilityStatus.mockRejectedValueOnce(new Error('boom'));
  renderWithKainBain(<QueuePopupModal counted={1} onClose={() => {}} />, { engineState: { openQueueDepth: 1 } });
  await waitFor(() => expect(screen.getByRole('alert')).toBeInTheDocument());
  api.observabilityStatus.mockResolvedValue({ observability: { queue: [] } });
  fireEvent.click(screen.getByRole('button', { name: 'Retry' }));
  await waitFor(() => expect(screen.getByText('Queue is Clear')).toBeInTheDocument());
});

test('dialog panel carries the shared modal surface (sized, surfaced, clipped)', async () => {
  renderWithKainBain(<QueuePopupModal counted={2} onClose={() => {}} />, { engineState: { openQueueDepth: 2 } });
  const dialog = await screen.findByRole('dialog');
  // Same panel contract as ChangelogModal: bounded width/height, theme
  // surface, rounded border, and overflow clipping — without it the rows
  // float over the page with no panel at all.
  expect(dialog).toHaveClass('max-w-2xl');
  expect(dialog).toHaveClass('bg-surface-container');
  expect(dialog).toHaveClass('overflow-hidden');
});

test('reconciliation note shows counts', async () => {
  renderWithKainBain(<QueuePopupModal counted={3} onClose={() => {}} />, { engineState: { openQueueDepth: 3 } });
  await waitFor(() => expect(screen.getByTestId('queue-reconciliation')).toBeInTheDocument());
  expect(screen.getByTestId('queue-reconciliation')).toHaveTextContent('3 open tasks counted · 1 shown');
});

test('counted-but-empty queue says nothing runs next and explains the gap', async () => {
  // All counted tasks are failed/waiting-human: the dispatch list is empty,
  // so the header must not claim "#1 runs next".
  api.observabilityStatus.mockResolvedValue({ observability: { queue: [] } });
  renderWithKainBain(<QueuePopupModal counted={3} onClose={() => {}} />, { engineState: { openQueueDepth: 3 } });
  await waitFor(() => expect(screen.getByText('Queue is Clear')).toBeInTheDocument());
  expect(screen.getByText(/#— runs next/)).toBeInTheDocument();
  expect(screen.queryByText(/#1 runs next/)).not.toBeInTheDocument();
  const note = screen.getByTestId('queue-reconciliation');
  expect(note).toHaveTextContent('3 open tasks counted · 0 shown');
  expect(note.parentElement).toHaveTextContent(/human-stage tasks count toward the number but never dispatch/);
});

test('a failed refresh keeps the last known rows visible under the alert', async () => {
  renderWithKainBain(<QueuePopupModal counted={1} onClose={() => {}} />, { engineState: { openQueueDepth: 1 } });
  await waitFor(() => expect(screen.getByTestId('queue-item-task-1')).toBeInTheDocument());

  // Push a failing refresh through the real observability event bus (the
  // hook subscribes to it; the event debounce fires one refresh ~500ms later).
  api.observabilityStatus.mockRejectedValueOnce(new Error('network down'));
  act(() => {
    invalidateObservability('tasks-changed', { taskId: 'task-1' });
  });
  await waitFor(() => expect(screen.getByRole('alert')).toBeInTheDocument(), { timeout: 3000 });
  // Fail-safe: the previously loaded row is still rendered under the alert.
  expect(screen.getByTestId('queue-item-task-1')).toBeInTheDocument();
  expect(screen.getByRole('alert')).toHaveTextContent('Showing the last known queue below');

  // Retry recovers: the alert clears and the row is still there.
